his.note.value.trim()"><?php echo \App\Core\CSRF::field();?><input class="form-control form-control-sm mb-1" name="note" placeholder="Motivo da recusa" required><button class="btn btn-sm btn-outline-danger w-100">Recusar</button></form><?php endif;?></td></tr>
